import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
/** Actual placement, installation, CHANT, turns and 裂界 produce every away possession; only initial deal/stats are arranged. */
export function makeR6OtherworldScenario(players:{id:string;name:string}[],second=false):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'白魔術師シェリム');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[b]!.permanent!.spirit=(s.players[b]!.permanent!.spirit??0)-gameStats(s,b).spirit;
 const rift=takeCard(s,a,'a2-p14-r2c2'),follower=takeCard(s,b,'兵士'),book=takeCard(s,b,'魔導書'),chant=takeCard(s,b,'氷狼乱舞陣'),revelation=takeCard(s,d,'a2-p02-r1c2'),dawn=takeCard(s,d,'a2-p01-r1c2');s.players[d]!.hand=s.players[d]!.hand.filter(id=>id!==dawn);s.deck.push(dawn);const wishes=['a2-p04-r3c2','a2-p04-r3c3'].map(id=>takeCard(s,c,id));trimHand(s,a,rift);trimHand(s,b,follower,book,chant);trimHand(s,c,...wishes);trimHand(s,d,revelation);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`S30_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('S30_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('S30_FIXTURE_CARDS');}
 function until(done:()=>boolean,dice=Array(100).fill(1)){for(let n=0;n<300;n++){if(done())return;const w=s.windows?.at(-1);if(!w)throw Error('S30_FIXTURE_WINDOW');act(w.participants[w.cursor]!,{type:'PASS'},dice);}throw Error('S30_FIXTURE_LIMIT');}
 function close(dice:number[]){const id=s.windows!.at(-1)!.id;until(()=>s.windows?.at(-1)?.id!==id,dice);}
 function nextAction(owner:string){for(let n=0;n<60;n++){const actor=s.seatOrder[s.turnSeat]!;if(s.phase==='action'&&actor===owner)return;if(s.phase==='turn-start')act(actor,{type:'START_TURN'});else if(s.phase==='draw')act(actor,{type:'CHOOSE_DRAW',draw:false});else if(s.phase==='action')act(actor,{type:'PASS_ACTION'});else if(s.phase==='withdrawal')act(actor,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment'){const keep=actor===a?[rift]:actor===b?[book,chant]:actor===c?wishes:[revelation];act(actor,{type:'END_TURN',discardIds:s.players[actor]!.hand.filter(id=>!keep.includes(id)).slice(0,Math.max(0,s.players[actor]!.hand.length-gameStats(s,actor).handLimit))});until(()=>!s.windows?.length);}else throw Error('S30_FIXTURE_TURN');}throw Error('S30_FIXTURE_TURN_LIMIT');}
 act(a,{type:'PASS_SETUP'});act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:follower});readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'CHANT',cardInstanceId:rift});nextAction(b);act(b,{type:'PLAY_TURN_CARD',cardInstanceIds:[book]});until(()=>!s.windows?.length);nextAction(a);act(a,{type:'PASS_ACTION'});nextAction(b);act(b,{type:'CHANT',cardInstanceId:chant});nextAction(a);act(a,{type:'ATTACK',cardInstanceId:rift,targetIds:[b],dedicated:true});until(()=>s.windows?.at(-1)?.kind==='lifetime-effect-choice');act(a,{type:'CHOOSE_LIFETIME_EFFECT',choice:'apply'});close([6,6]);close([1,1]);until(()=>!s.windows?.length);if(s.players[b]!.presence!=='otherworld')throw Error('S30_FIXTURE_OTHERWORLD');nextAction(c);if(!second)return s;
 act(c,{type:'PLAY_TURN_CARD',cardInstanceId:'a2-p04-r3c2',mode:'wish'});until(()=>s.windows?.at(-1)?.kind==='wish');act(c,{type:'CHOOSE_WISH',decisionId:viewFor(s,c).wish!.decisionId,source:{kind:'hand',ownerId:a}});until(()=>!s.windows?.length);nextAction(c);return s;
}
